commit 2e1fa8ab2826fb812be3a7c587f48d59c83f405c
Author: Irakli Gozalishvili <contact@gozala.io>
Date:   Fri Dec 10 15:36:20 2021 -0800

    buffer: fix `Blob` constructor on various `TypedArray`s

    Fixes: https://github.com/nodejs/node/issues/40705

    PR-URL: https://github.com/nodejs/node/pull/40706
    Reviewed-By: Robert Nagy <ronagy@icloud.com>
    Reviewed-By: Antoine du Hamel <duhamelantoine1995@gmail.com>
    Reviewed-By: Minwoo Jung <nodecorelab@gmail.com>
    Reviewed-By: James M Snell <jasnell@gmail.com>

diff --git a/lib/internal/blob.js b/lib/internal/blob.js
index 7edc66a7046..b4b3da8d604 100644
--- a/lib/internal/blob.js
+++ b/lib/internal/blob.js
@@ -114,10 +114,10 @@ function getSource(source, endings) {

   // We copy into a new Uint8Array because the underlying
   // BackingStores are going to be detached and owned by
-  // the Blob. We also don't want to have to worry about
-  // byte offsets.
-  source = new Uint8Array(source);
-  return [source.byteLength, source];
+  // the Blob.
+  const { buffer, byteOffset, byteLength } = source;
+  const slice = buffer.slice(byteOffset, byteOffset + byteLength);
+  return [byteLength, new Uint8Array(slice)];
 }

 class Blob {
diff --git a/test/parallel/test-blob.js b/test/parallel/test-blob.js
index 39301e85c9c..53b9ddb0cb3 100644
--- a/test/parallel/test-blob.js
+++ b/test/parallel/test-blob.js
@@ -229,3 +229,18 @@ assert.throws(() => new Blob({}), {
     });
   });
 }
+
+(async () => {
+  const blob = new Blob([
+    new Uint8Array([0x50, 0x41, 0x53, 0x53]),
+    new Int8Array([0x50, 0x41, 0x53, 0x53]),
+    new Uint16Array([0x4150, 0x5353]),
+    new Int16Array([0x4150, 0x5353]),
+    new Uint32Array([0x53534150]),
+    new Int32Array([0x53534150]),
+    new Float32Array([0xD341500000]),
+  ]);
+
+  assert.strictEqual(blob.size, 28);
+  assert.strictEqual(blob.type, '');
+})().then(common.mustCall());
